body:
:root {
  --bg: #eef4fb;
  --bg-soft: #f8fbff;
  --bg-deep: #dfe9f8;
  --surface: rgba(255, 255, 255, 0.84);
  --surface-strong: rgba(255, 255, 255, 0.94);
  --surface-elevated: rgba(255, 255, 255, 0.98);
  --line: rgba(17, 57, 128, 0.1);
  --line-strong: rgba(17, 57, 128, 0.18);
  --text: #11233f;
  --text-muted: #60718d;
  --text-soft: #7e8ca4;
  --text-on-dark: rgba(243, 247, 255, 0.92);
  --text-on-dark-soft: rgba(219, 229, 247, 0.74);
  --primary: #2a68e8;
  --primary-strong: #103b91;
  --primary-soft: rgba(42, 104, 232, 0.12);
  --navy: #081b3a;
  --navy-deep: #031126;
  --success: #177255;
  --warning: #a8761a;
  --danger: #a74854;
  --shadow-soft: 0 14px 34px rgba(6, 23, 52, 0.08);
  --shadow-strong: 0 22px 60px rgba(6, 23, 52, 0.14);
  --radius-hero: 18px;
  --radius-xl: 8px;
  --radius-lg: 8px;
  --radius-md: 8px;
  --radius-sm: 8px;
  --font-sans: "Manrope", "Segoe UI", sans-serif;
  --font-display: "Sora", "Segoe UI", sans-serif;
}

* {
  box-sizing: border-box;
}

html {
  background: linear-gradient(180deg, #fbfdff 0%, #edf4fb 100%);
}

body {
  margin: 0;
  min-height: 100vh;
  font-size: 14px;
  font-family: var(--font-sans);
  color: var(--text);
  background:
    radial-gradient(circle at top left, rgba(81, 139, 255, 0.1), transparent 28%),
    radial-gradient(circle at 85% 18%, rgba(9, 42, 112, 0.08), transparent 26%),
    linear-gradient(180deg, #f8fbff 0%, #eef4fb 54%, #e7eef8 100%);
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.14) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.14) 1px, transparent 1px);
  background-size: 96px 96px;
  mask-image: radial-gradient(circle at center, rgba(0, 0, 0, 0.45), transparent 82%);
  opacity: 0.28;
}

body.app-authenticated {
  overflow: hidden;
}

body.app-authenticated .workspace-shell {
  min-height: 100vh;
  height: 100vh;
  overflow: hidden;
}

body.app-authenticated .workspace {
  min-height: 100vh;
  height: 100vh;
}

body.app-logged-out .login-shell {
  min-height: 100vh;
}

body.app-logged-out {
  overflow: hidden;
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  cursor: pointer;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.login-shell,
.workspace-shell {
  min-height: 100vh;
}

.login-shell[hidden],
.workspace-shell[hidden] {
  display: none !important;
}

.login-card [hidden] {
  display: none !important;
}

.login-shell {
  display: grid;
  place-items: center;
  padding: 16px;
  height: 100vh;
  height: 100dvh;
}

.login-stage {
  width: min(100%, 1160px);
  min-height: min(580px, calc(100dvh - 32px));
  height: auto;
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(350px, 0.8fr);
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface);
  box-shadow: 0 22px 52px rgba(6, 23, 52, 0.11);
}

.login-showcase,
.login-panel {
  position: relative;
}

.login-showcase {
  display: grid;
  align-items: center;
  min-height: 0;
  padding: clamp(30px, 4vw, 42px) clamp(36px, 5vw, 64px);
  background:
    radial-gradient(circle at 88% 8%, rgba(92, 147, 255, 0.18), transparent 26%),
    linear-gradient(155deg, #f8fbff 0%, #edf4ff 100%);
}

.login-showcase::before {
  content: "";
  position: absolute;
  inset: auto -100px -130px auto;
  width: 310px;
  height: 310px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(42, 104, 232, 0.18), rgba(42, 104, 232, 0));
}

.login-showcase::after {
  content: none;
}

.login-showcase-inner {
  position: relative;
  z-index: 1;
  display: grid;
  align-content: start;
  gap: 20px;
}

.brand-lockup,
.hero-copy,
.login-card-copy,
.brand-block,
.sidebar-brand-copy,
.metric-card,
.chart-card,
.panel-card,
.table-card,
.timeline,
.empty-state {
  display: grid;
  gap: 14px;
}

.brand-lockup {
  max-width: 360px;
  gap: 8px;
}

.login-brand-logo {
  width: min(100%, 228px);
  height: auto;
  filter: drop-shadow(0 16px 36px rgba(16, 59, 145, 0.12));
}

.brand-kicker {
  margin: 0;
  color: var(--primary-strong);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.login-showcase h1,
.login-card h2,
.topbar h1,
.module-header h2,
.table-card h2,
.panel-card h2,
.chart-card h2,
.timeline h2,
.metric-card strong,
.empty-state h2,
.sidebar-brand-copy strong {
  margin: 0;
  font-family: var(--font-display);
}

.login-showcase h1 {
  max-width: 18ch;
  font-size: clamp(2rem, 2.8vw, 2.8rem);
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.045em;
}

.login-copy,
.login-card p,
.brand-note,
.module-copy,
.table-card p,
.panel-card p,
.chart-card p,
.timeline p,
.metric-card p,
.empty-state p,
.status-banner,
.user-chip p,
.topbar p,
.field input::placeholder,
.field textarea::placeholder,
.field span,
.form-message,
.toast {
  color: var(--text-muted);
}

.login-copy,
.module-copy,
.brand-note,
.panel-card p,
.chart-card p,
.timeline p,
.table-card p,
.metric-card p {
  margin: 0;
  line-height: 1.55;
}

.login-copy {
  max-width: 52ch;
  font-size: 0.88rem;
  font-weight: 500;
  line-height: 1.65;
}

.eyebrow,
.meta-chip {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  min-height: 26px;
  padding: 5px 9px;
  border-radius: 8px;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0;
  text-transform: uppercase;
}

.eyebrow {
  background: var(--primary-soft);
  color: var(--primary-strong);
}

.eyebrow-subtle {
  background: rgba(16, 59, 145, 0.08);
}

.login-panel {
  display: grid;
  align-items: center;
  padding: clamp(26px, 3.2vw, 42px);
  background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
}

.login-panel::before {
  content: none;
  position: absolute;
  inset: 26px auto auto 26px;
  width: 140px;
  height: 140px;
  border-radius: 28px;
  background: radial-gradient(circle, rgba(42, 104, 232, 0.12), rgba(42, 104, 232, 0));
}

.login-panel-shell {
  position: relative;
  z-index: 1;
  display: grid;
  height: 100%;
  align-items: center;
}

.login-theme-actions {
  display: flex;
  justify-content: flex-end;
  margin-bottom: 14px;
}

.login-theme-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  min-width: 32px;
  padding: 0;
  border: 1px solid rgba(22, 66, 154, 0.1);
  border-radius: 8px;
  background: rgba(22, 66, 154, 0.06);
  color: var(--primary-strong);
  box-shadow: none;
}

.login-theme-toggle:hover {
  background: rgba(22, 66, 154, 0.12);
}

.theme-toggle-icon {
  display: inline-grid;
  width: 18px;
  height: 18px;
  place-items: center;
  border-radius: 50%;
  background: rgba(42, 104, 232, 0.12);
  font-size: 0.84rem;
  line-height: 1;
}

.login-card {
  width: 100%;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.login-card-copy {
  margin-bottom: 22px;
}

.login-card-copy h2 {
  font-size: clamp(1.45rem, 1.8vw, 1.8rem);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.035em;
}

.auth-form,
.stack,
.page-content,
.grid,
.split-layout,
.stats-grid,
.charts-grid {
  display: grid;
  gap: 12px;
}

.field {
  display: grid;
  gap: 8px;
}

.field span,
.table-card th,
.user-chip strong {
  font-weight: 700;
}

.field input,
.field select,
.field textarea,
.search-field input {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid rgba(16, 59, 145, 0.12);
  border-radius: 8px;
  background: rgba(251, 253, 255, 0.94);
  color: var(--text);
  transition: border-color 180ms ease, box-shadow 180ms ease, background-color 180ms ease, transform 180ms ease;
}

.field input:disabled,
.field select:disabled,
.field textarea:disabled {
  color: var(--text-soft);
  background: rgba(240, 244, 251, 0.82);
  cursor: not-allowed;
}

.field textarea {
  min-height: 92px;
  resize: vertical;
}

.field input:focus,
.field select:focus,
.field textarea:focus,
.search-field input:focus {
  outline: none;
  border-color: rgba(42, 104, 232, 0.38);
  background: var(--surface-elevated);
  box-shadow: 0 0 0 4px rgba(42, 104, 232, 0.12);
}

.search-field input:disabled {
  background: rgba(247, 250, 255, 0.96);
  color: var(--text-soft);
  cursor: not-allowed;
}

.button,
.icon-button {
  border: 0;
  border-radius: 8px;
  transition: transform 180ms ease, background-color 180ms ease, color 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
}

.button {
  padding: 10px 14px;
  font-weight: 700;
}

.button.primary {
  color: #ffffff;
  background: linear-gradient(135deg, #2666ea 0%, #103b91 100%);
  box-shadow: 0 18px 38px rgba(38, 102, 234, 0.24);
}

.button.secondary,
.button.ghost,
.icon-button {
  color: var(--primary-strong);
  background: rgba(22, 66, 154, 0.08);
  box-shadow: inset 0 0 0 1px rgba(22, 66, 154, 0.06);
}

.button:hover,
.icon-button:hover {
  transform: translateY(-1px);
}

.button:disabled,
.icon-button:disabled {
  opacity: 0.58;
  cursor: not-allowed;
  transform: none;
}

.button.primary:hover {
  box-shadow: 0 20px 40px rgba(38, 102, 234, 0.3);
}

.button.ghost {
  background: rgba(255, 255, 255, 0.72);
}

.form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.form-actions .button {
  min-width: 132px;
}

.action-workspace,
.action-subview {
  display: grid;
  gap: 12px;
}

.action-workspace-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  padding: 4px 2px;
}

.action-workspace-header h2,
.action-workspace-header p {
  margin: 0;
}

.action-workspace-header h2 {
  margin-top: 4px;
  font-family: var(--font-display);
  font-size: clamp(1.28rem, 1.7vw, 1.68rem);
  color: var(--navy);
}

.action-workspace-header > div > p:last-child {
  margin-top: 5px;
  color: var(--text-muted);
  font-size: 0.84rem;
}

.action-filter-card {
  padding: 12px;
  border: 1px solid rgba(17, 57, 128, 0.09);
  border-radius: 8px;
  background: rgba(247, 250, 255, 0.78);
}

.action-filter-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
  color: var(--navy);
  font-size: 0.82rem;
}

.action-filter-heading .button {
  min-width: auto;
  padding: 6px 9px;
  font-size: 0.74rem;
}

.action-filter-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.action-filter-grid .field {
  gap: 4px;
}

.action-filter-grid .field span {
  font-size: 0.7rem;
}

.action-filter-grid input,
.action-filter-grid select {
  min-height: 34px;
  padding: 7px 9px;
  font-size: 0.78rem;
}

.action-filter-result {
  margin: 10px 0 0;
  color: var(--text-muted);
  font-size: 0.78rem;
}

.action-portfolio-card {
  min-height: 0;
}

.action-portfolio-card .table-scroll {
  margin-top: 0;
  overflow: visible;
}

.action-table {
  min-width: 1100px;
  table-layout: fixed;
  font-size: 0.72rem;
}

.action-date-column {
  width: 84px;
}

.action-meeting-column,
.action-requester-column,
.action-owner-column {
  width: 12%;
}

.action-subject-column {
  width: 10%;
}

.action-plan-column {
  width: 29%;
}

.action-priority-column {
  width: 6%;
}

.action-status-column {
  width: 6%;
}

.action-attachment-column {
  width: 6%;
}

.attachment-link {
  display: inline-flex;
  min-width: auto;
  padding: 5px 7px;
  font-size: 0.66rem;
  text-decoration: none;
}

.text-muted {
  color: var(--text-muted);
  font-size: 0.7rem;
}

.action-table th,
.action-table td {
  padding: 9px 6px;
  line-height: 1.35;
  overflow-wrap: anywhere;
  white-space: normal;
}

.action-table th {
  font-size: 0.62rem;
  letter-spacing: 0.025em;
}

.action-table td {
  color: #314864;
  font-weight: 550;
}

.action-table .action-date-cell {
  padding-left: 4px;
  padding-right: 4px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.action-table .action-plan-cell {
  color: var(--navy);
  font-size: 0.77rem;
  font-weight: 700;
  line-height: 1.45;
}

.action-table .badge {
  max-width: 100%;
  padding: 3px 5px;
  font-size: 0.66rem;
  line-height: 1.2;
  text-align: center;
  justify-content: center;
  white-space: normal;
}

.action-create-form .form-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.meeting-workspace .panel-card {
  max-width: none;
}

.meeting-toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  justify-content: space-between;
  padding: 12px;
  border: 1px solid rgba(16, 59, 145, 0.08);
  border-radius: 8px;
  background: rgba(16, 59, 145, 0.04);
}

.meeting-view-actions {
  display: flex;
  justify-content: flex-end;
  margin-bottom: 12px;
}

.meeting-history-toolbar {
  display: grid;
  grid-template-columns: minmax(180px, 1fr) 170px auto;
  gap: 10px;
  align-items: end;
  margin-bottom: 12px;
  padding: 12px;
  border: 1px solid rgba(16, 59, 145, 0.08);
  border-radius: 8px;
  background: rgba(16, 59, 145, 0.04);
}

.meeting-history-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.meeting-history-toolbar .action-filter-result {
  grid-column: 1 / -1;
  margin: 0;
}

.meeting-timer {
  display: grid;
  gap: 4px;
  min-width: 118px;
  text-align: right;
}

.meeting-timer span {
  color: var(--text-soft);
  font-size: 0.82rem;
  font-weight: 700;
}

.meeting-timer strong {
  color: var(--primary-strong);
  font-family: var(--font-display);
  font-size: 1.18rem;
  letter-spacing: 0;
}

.login-form-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
}

.login-support {
  display: grid;
  gap: 8px;
  margin-top: 18px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
}

.login-support button {
  justify-self: start;
  padding: 8px 11px;
  border: 1px solid rgba(22, 66, 154, 0.1);
  border-radius: 8px;
  background: rgba(22, 66, 154, 0.06);
  color: var(--primary-strong);
  font-size: 0.78rem;
  font-weight: 700;
}

.login-support button:hover {
  color: var(--primary);
  background: rgba(22, 66, 154, 0.1);
}

.login-support p {
  margin: 0;
  color: var(--text-muted);
  font-size: 0.74rem;
  line-height: 1.45;
}

.reset-code-info {
  margin: 0;
  padding: 10px 12px;
  border: 1px solid rgba(42, 104, 232, 0.16);
  border-radius: 8px;
  background: rgba(42, 104, 232, 0.07);
  color: var(--primary-strong);
  font-size: 0.78rem;
  line-height: 1.45;
}

.login-card.is-reset .login-support {
  display: none;
}

.topbar h1,
.chart-card strong,
.timeline strong {
  color: var(--text);
}

.workspace {
  min-height: 100vh;
  display: grid;
  grid-template-columns: 252px minmax(0, 1fr);
  gap: 12px;
  padding: 12px;
}

.sidebar {
  position: relative;
  display: flex;
  flex-direction: column;
  padding: 16px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 14px 34px rgba(6, 23, 52, 0.08);
  overflow: hidden;
}

.sidebar::before {
  content: none;
  position: absolute;
  inset: -140px auto auto -120px;
  width: 320px;
  height: 320px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(71, 128, 242, 0.34), rgba(71, 128, 242, 0));
}

.sidebar::after {
  content: none;
  position: absolute;
  inset: auto -100px 40px auto;
  width: 220px;
  height: 220px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(13, 59, 145, 0.3), rgba(13, 59, 145, 0));
}

.sidebar-header,
.topbar,
.module-header,
.row,
.topbar-actions,
.user-chip,
.counter-button,
.sidebar-brand {
  display: flex;
}

.sidebar-header {
  position: relative;
  z-index: 1;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 14px;
}

.sidebar-navigation {
  min-height: 0;
  overflow: auto;
}

.brand-block {
  position: relative;
  z-index: 1;
}

.sidebar-brand {
  align-items: center;
  gap: 11px;
  padding: 6px 4px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  box-shadow: none;
}

.sidebar-brand-mark {
  width: 38px;
  height: auto;
  flex: none;
  filter: none;
}

.sidebar-brand-copy strong {
  font-size: 0.9rem;
  line-height: 1.1;
  color: var(--navy);
}

.sidebar-brand-copy p,
.brand-note {
  color: var(--text-muted);
}

.brand-note {
  max-width: 26ch;
  margin: 6px 4px 0;
  font-size: 0.74rem;
  line-height: 1.42;
}

.sidebar-section-label {
  margin: 4px 4px 8px;
  color: var(--primary);
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.nav-list {
  position: relative;
  z-index: 1;
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 2px;
}

.nav-list button {
  position: relative;
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  padding: 6px 8px;
  border: 1px solid transparent;
  border-radius: 7px;
  background: transparent;
  color: #36506d;
  text-align: left;
  font-size: 0.78rem;
  font-weight: 650;
  line-height: 1.2;
}

.nav-list button::before {
  content: none;
}

.nav-list button:hover {
  color: var(--primary-strong);
  background: #f4f8fc;
}

.nav-list button.active {
  border-color: transparent;
  color: var(--primary-strong);
  background: #eaf2ff;
  box-shadow: none;
}

.nav-list button.active > span:last-child::after {
  content: "›";
  margin-left: auto;
  color: var(--primary);
  font-size: 1.15rem;
  line-height: 0;
}

.nav-list button.active > span:last-child {
  display: flex;
  align-items: center;
  width: 100%;
}

.nav-icon-frame {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  flex: none;
  border-radius: 7px;
  background: #eef3f6;
  color: #43657a;
}

.nav-list button.active .nav-icon-frame {
  background: #d9e9ff;
  color: var(--primary);
}

.nav-icon {
  width: 17px;
  height: 17px;
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.7;
}

.nav-list button[data-view="dashboard"] .nav-icon {
  fill: currentColor;
  stroke: none;
}

.sidebar-footer {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 8px;
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px solid #e7edf3;
}

.sidebar-user {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 3px 4px;
  color: var(--navy);
  font-size: 0.78rem;
}

.sidebar-user .avatar {
  width: 30px;
  height: 30px;
  font-size: 0.72rem;
  background: #e9f0f5;
  color: #2b5d79;
  box-shadow: none;
}

.footer-nav-list {
  gap: 2px;
}

.sidebar-logout {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 9px 10px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: #587085;
  text-align: left;
  font: inherit;
  font-size: 0.84rem;
  font-weight: 700;
}

.sidebar-logout:hover {
  color: var(--primary-strong);
  background: #f4f8fc;
}

.workspace-main {
  min-width: 0;
  min-height: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 12px;
}

.topbar {
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  min-height: 58px;
  padding: 10px 14px;
  border: 1px solid rgba(255, 255, 255, 0.66);
  border-radius: 8px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.92), rgba(246, 250, 255, 0.82)),
    linear-gradient(90deg, rgba(42, 104, 232, 0.08), transparent);
  box-shadow: var(--shadow-soft);
  backdrop-filter: blur(18px);
}

.topbar-heading {
  display: flex;
  align-items: center;
  gap: 10px;
}

.topbar h1 {
  font-size: clamp(1.1rem, 1.3vw, 1.38rem);
  letter-spacing: 0;
}

.topbar-actions {
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  flex-wrap: wrap;
}

.topbar-theme-toggle {
  width: 30px;
  height: 30px;
  min-width: 30px;
  padding: 0;
  border-color: rgba(22, 66, 154, 0.1);
  background: rgba(22, 66, 154, 0.06);
  color: var(--primary-strong);
}

.topbar-theme-toggle:hover {
  background: rgba(22, 66, 154, 0.12);
}

.search-field {
  display: none;
}

.search-field input {
  border-radius: 999px;
  padding-inline: 18px;
}

.counter-button {
  position: relative;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  gap: 0;
  padding: 0;
  border-radius: 8px;
}

.counter {
  position: absolute;
  top: -6px;
  right: -6px;
  min-width: 18px;
  height: 18px;
  padding: 1px 5px;
  text-align: center;
  border-radius: 999px;
  background: #2a68e8;
  color: #ffffff;
  font-size: 0.68rem;
  line-height: 16px;
  box-shadow: 0 8px 18px rgba(42, 104, 232, 0.24);
}

.icon {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.9;
}

.user-chip {
  align-items: center;
  gap: 12px;
  padding: 6px 10px 6px 6px;
  border: 1px solid rgba(17, 57, 128, 0.1);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.86);
  box-shadow: 0 14px 28px rgba(6, 23, 52, 0.06);
}

.user-chip p,
.topbar p {
  margin: 4px 0 0;
}

.avatar {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: linear-gradient(145deg, #2a68e8 0%, #103b91 100%);
  color: #ffffff;
  font-weight: 800;
  box-shadow: 0 16px 32px rgba(16, 59, 145, 0.22);
}

.content {
  min-height: 0;
  overflow: auto;
  padding: 0;
}

.page-content {
  gap: 12px;
  padding-right: 0;
}

.module-header {
  display: none;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;
  padding: 4px 2px;
}

.module-header h2 {
  margin-top: 10px;
  font-size: clamp(1.8rem, 2.4vw, 2.7rem);
  line-height: 1.06;
  letter-spacing: 0;
}

.stats-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.charts-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.split-layout {
  grid-template-columns: minmax(0, 1.12fr) minmax(340px, 0.88fr);
}

.administration-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.administration-summary article {
  display: grid;
  gap: 3px;
  min-height: 104px;
  padding: 15px 16px;
  border: 1px solid rgba(17, 57, 128, 0.09);
  border-radius: 8px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.94), rgba(234, 242, 255, 0.82));
  box-shadow: var(--shadow-soft);
}

.administration-summary span,
.administration-summary small {
  color: var(--text-muted);
  font-weight: 650;
}

.administration-summary span {
  font-size: 0.75rem;
}

.administration-summary strong {
  color: var(--primary-strong);
  font-family: var(--font-display);
  font-size: 1.65rem;
  line-height: 1.1;
}

.administration-summary small {
  font-size: 0.68rem;
}

.administration-layout {
  grid-template-columns: minmax(0, 1fr) minmax(300px, 0.52fr);
  align-items: start;
}

.administration-export-actions {
  display: flex;
  justify-content: flex-end;
}

.administration-form {
  position: sticky;
  top: 12px;
}

.administration-meetings table {
  min-width: 600px;
}

.administration-meetings th:last-child,
.administration-meetings td:last-child {
  width: 1%;
  padding-left: 16px;
  white-space: nowrap;
}

.administration-users table {
  min-width: 760px;
}

.administration-users td:nth-child(1),
.administration-users td:nth-child(2) {
  font-weight: 700;
}

.single-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
}

.metric-card,
.chart-card,
.panel-card,
.table-card,
.timeline,
.empty-state,
.status-banner {
  position: relative;
  padding: 16px;
  border: 1px solid rgba(17, 57, 128, 0.09);
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.9), rgba(248, 251, 255, 0.82));
  box-shadow: var(--shadow-soft);
  backdrop-filter: blur(18px);
}

.metric-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 16px;
  right: 16px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(42, 104, 232, 0.44), transparent);
}

.metric-card strong {
  display: block;
  margin: 10px 0 4px;
  font-size: clamp(1.55rem, 2vw, 2.1rem);
  letter-spacing: 0;
}

.metric-card p,
.chart-card p,
.panel-card p,
.empty-state p {
  margin: 0;
}

.table-scroll {
  margin-top: 12px;
  overflow-x: auto;
}

table {
  width: 100%;
  min-width: 640px;
  border-collapse: separate;
  border-spacing: 0;
}

th,
td {
  padding: 10px 0;
  text-align: left;
  vertical-align: top;
}

th {
  padding-top: 0;
  padding-bottom: 10px;
  font-size: 0.72rem;
  letter-spacing: 0;
  text-transform: uppercase;
  color: var(--text-soft);
}

tbody td {
  border-top: 1px solid rgba(17, 57, 128, 0.08);
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  border: 1px solid transparent;
  border-radius: 999px;
  background: rgba(42, 104, 232, 0.08);
  font-size: 0.76rem;
  font-weight: 700;
}

.badge.low,
.badge.success,
.badge.done,
.badge.resolved {
  color: var(--success);
  background: rgba(23, 114, 85, 0.12);
}

.badge.medium,
.badge.warning {
  color: var(--warning);
  background: rgba(168, 118, 26, 0.13);
}

.badge.high,
.badge.critical,
.badge.danger {
  color: var(--danger);
  background: rgba(167, 72, 84, 0.12);
}

.badge.info,
.badge.open,
.badge.in_progress,
.badge.scheduled,
.badge.investigating {
  color: var(--primary-strong);
  background: rgba(42, 104, 232, 0.12);
}

.badge.pending {
  color: var(--text-soft);
  background: rgba(76, 91, 117, 0.1);
}

.audit-live-strip {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text-soft);
  font-size: 0.78rem;
}

.audit-live-strip strong { color: var(--success); }
.audit-live-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--success);
  box-shadow: 0 0 0 4px rgba(23, 114, 85, 0.12);
}

.audit-filter-grid { grid-template-columns: minmax(220px, 1.5fr) repeat(3, minmax(150px, 1fr)); }
.audit-stats-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}
.audit-metric-card {
  min-height: 84px;
  padding: 11px 12px;
  border: 1px solid rgba(17, 57, 128, 0.12);
  border-left: 3px solid var(--primary);
  border-radius: 8px;
  background: var(--surface, #fff);
  box-shadow: 0 5px 18px rgba(16, 59, 145, 0.06);
}
.audit-metric-card span,
.audit-metric-card small { display: block; color: var(--text-muted); font-size: 0.68rem; }
.audit-metric-card span { color: var(--text-soft); font-weight: 700; }
.audit-metric-card strong { display: block; margin: 3px 0 1px; font-family: var(--font-display); font-size: 1.42rem; }
.audit-overview-grid { display: grid; grid-template-columns: minmax(0, 1.45fr) minmax(280px, 0.85fr); gap: 10px; }
.audit-overview-card {
  padding: 13px;
  border: 1px solid rgba(17, 57, 128, 0.1);
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(255,255,255,.94), rgba(248,251,255,.88));
  box-shadow: var(--shadow-soft);
}
.audit-card-heading { display: flex; align-items: start; justify-content: space-between; gap: 12px; margin-bottom: 10px; }
.audit-card-heading span { color: var(--text-muted); font-size: .62rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
.audit-card-heading h3 { margin: 2px 0 0; font-size: .9rem; }
.audit-card-heading small { color: var(--text-muted); font-size: .65rem; }
.audit-progress-list,
.audit-status-list { display: grid; gap: 8px; }
.audit-progress-row { display: grid; grid-template-columns: minmax(155px, .9fr) minmax(120px, 1.2fr) 34px; align-items: center; gap: 10px; }
.audit-progress-person { display: flex; align-items: center; gap: 8px; min-width: 0; }
.audit-progress-person div { min-width: 0; }
.audit-progress-person strong,
.audit-progress-person small { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.audit-progress-person strong { font-size: .73rem; }
.audit-progress-person small { color: var(--text-muted); font-size: .61rem; }
.audit-avatar { display: grid; place-items: center; width: 25px; height: 25px; flex: 0 0 25px; border-radius: 6px; color: var(--primary-strong); background: rgba(42,104,232,.11); font-size: .62rem; font-weight: 800; }
.audit-progress-track,
.audit-status-track { height: 5px; overflow: hidden; border-radius: 999px; background: rgba(76,91,117,.14); }
.audit-progress-track span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--primary), #4ecaa8); }
.audit-progress-row b { text-align: right; font-size: .68rem; }
.audit-status-row { display: grid; grid-template-columns: 92px 1fr 28px; align-items: center; gap: 8px; font-size: .69rem; }
.audit-status-row > span { color: var(--text-soft); }
.audit-status-row > strong { text-align: right; }
.audit-status-track i { display: block; height: 100%; border-radius: inherit; background: #8b98ab; }
.audit-status-track.in_progress i { background: #dda62f; }
.audit-status-track.done i { background: #31b795; }
.audit-table-card,
[data-audit-filters] { padding: 8px 10px; }
[data-audit-filters] .action-filter-heading { margin-bottom: 4px; }
[data-audit-filters] .action-filter-heading h3 { margin: 0; font-size: .75rem; }
[data-audit-filters] .action-filter-heading .button { min-height: 26px; padding: 3px 7px; font-size: .65rem; }
[data-audit-filters] .action-filter-grid { gap: 5px; }
[data-audit-filters] .field { gap: 2px; }
[data-audit-filters] .field span { font-size: .61rem; }
[data-audit-filters] .field input,
[data-audit-filters] .field select { min-height: 29px; padding: 4px 7px; font-size: .68rem; }
[data-audit-filters] .action-filter-result { margin-top: 4px; font-size: .65rem; }
.audit-table-card { padding: 9px 10px; }
.audit-table-card .table-card-header { min-height: 0; align-items: center; }
.audit-table-card .table-card-header h3 { margin: 0; font-size: .8rem; }
.audit-table-card .table-card-header small { color: var(--text-muted); font-size: .62rem; }
.audit-table-card .table-scroll { margin-top: 6px; max-height: 58vh; overflow: auto; }
.audit-table-card thead th { position: sticky; top: 0; z-index: 2; background: var(--surface-strong); }
.audit-actions-table { min-width: 1160px; table-layout: fixed; }
.audit-actions-table th,
.audit-actions-table td { padding: 5px 7px; font-size: .68rem; }
.audit-actions-table th { padding: 5px 7px; font-size: .6rem; }
.audit-actions-table th:first-child,
.audit-actions-table td:first-child { padding-left: 0; }
.audit-actions-table th:last-child,
.audit-actions-table td:last-child { padding-right: 0; }
.audit-col-check { width: 36px; }
.audit-col-pilar { width: 10%; }
.audit-col-question { width: 7%; }
.audit-col-action { width: 31%; }
.audit-col-target { width: 27%; }
.audit-col-owner { width: 12%; }
.audit-col-status { width: 13%; }
.audit-check-cell { text-align: center; }
.audit-text-cell { line-height: 1.28; }
.audit-status-cell { display: grid; justify-items: start; gap: 3px; }
.audit-status-line { display: flex; align-items: center; gap: 4px; }
.audit-status-cell small { color: var(--text-muted); font-size: 0.59rem; }
.audit-action-button { min-width: 62px; min-height: 25px; padding: 3px 7px; font-size: .64rem; }
.audit-admin-check {
  display: inline-grid;
  place-items: center;
  width: 25px;
  height: 25px;
  padding: 0;
  border: 1px solid rgba(23,114,85,.3);
  border-radius: 6px;
  color: var(--success);
  background: rgba(23,114,85,.1);
  font-size: .84rem;
  font-weight: 900;
  cursor: pointer;
}
.audit-admin-check:hover { color: #fff; background: var(--success); }

@media (max-width: 900px) {
  .audit-filter-grid { grid-template-columns: 1fr 1fr; }
  .audit-stats-grid { grid-template-columns: 1fr 1fr; }
  .audit-overview-grid { grid-template-columns: 1fr; }
}

@media (max-width: 620px) {
  .audit-filter-grid { grid-template-columns: 1fr; }
  .audit-stats-grid { grid-template-columns: 1fr 1fr; }
  .audit-progress-row { grid-template-columns: minmax(135px, .9fr) minmax(90px, 1fr) 32px; gap: 7px; }
  .audit-live-strip { flex-wrap: wrap; }
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.form-grid .field.full {
  grid-column: 1 / -1;
}

.attachment-field {
  grid-column: 1 / -1;
  padding: 10px;
  border: 1px dashed rgba(42, 104, 232, 0.28);
  border-radius: 8px;
  background: rgba(42, 104, 232, 0.035);
}

.attachment-field input[type="file"] {
  padding: 8px;
  background: #ffffff;
}

.attachment-field small {
  color: var(--text-muted);
  font-size: 0.72rem;
}

.chart-card ul,
.timeline ol {
  list-style: none;
  padding: 0;
  margin: 12px 0 0;
  display: grid;
  gap: 10px;
}

.row {
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
}

.bar-track {
  width: 100%;
  height: 7px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(42, 104, 232, 0.12);
}

.bar-fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #2a68e8 0%, #103b91 100%);
}

.timeline li {
  padding-left: 12px;
  border-left: 1px solid rgba(42, 104, 232, 0.18);
}

.timeline time {
  display: block;
  margin-top: 6px;
  color: var(--text-muted);
  font-size: 0.88rem;
}

.status-banner {
  margin-bottom: 2px;
  background: linear-gradient(135deg, rgba(42, 104, 232, 0.12), rgba(255, 255, 255, 0.96));
}

.empty-state {
  min-height: 148px;
  place-items: center;
  text-align: center;
}

.empty-state-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
}

.toast-region {
  position: fixed;
  right: 22px;
  bottom: 22px;
  z-index: 100;
  display: grid;
  gap: 10px;
}

.toast {
  min-width: 260px;
  max-width: 360px;
  padding: 12px 14px;
  border: 1px solid rgba(255, 255, 255, 0.72);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: var(--shadow-soft);
}

.toast.success {
  border-color: rgba(23, 114, 85, 0.2);
}

.toast.error,
.form-message {
  color: var(--danger);
}

.toast.warning {
  color: #8a5c11;
}

.button.is-busy {
  cursor: progress;
  opacity: 0.78;
}

.page-content.is-refreshing {
  transition: opacity 140ms ease;
}

.mobile-only {
  display: none;
}

/* Refinement pass: keeps the interface compact and presentation-ready. */
.login-stage,
.login-card,
.highlight-card,
.sidebar,
.sidebar-brand,
.topbar,
.metric-card,
.chart-card,
.panel-card,
.table-card,
.timeline,
.empty-state,
.status-banner,
.field input,
.field select,
.field textarea,
.button,
.icon-button,
.user-chip {
  border-radius: 8px;
}

.module-header {
  display: none !important;
}

.search-field {
  display: none !important;
}

.topbar .eyebrow {
  min-height: 24px;
  padding: 4px 8px;
  background: rgba(42, 104, 232, 0.08);
}

.panel-card h2,
.table-card h2,
.chart-card h2,
.timeline h2 {
  font-size: clamp(1rem, 1.12vw, 1.18rem);
  line-height: 1.2;
}

.field span {
  font-size: 0.82rem;
}

.meeting-action-form {
  gap: 10px;
}

@media (max-width: 1180px) {
  .workspace {
    grid-template-columns: 1fr;
    padding: 14px;
  }

  .sidebar {
    position: fixed;
    inset: 14px auto 14px 14px;
    width: min(86vw, 336px);
    z-index: 40;
    transform: translateX(calc(-100% - 20px));
    transition: transform 220ms ease;
  }

  .sidebar.is-open {
    transform: translateX(0);
  }

  .mobile-only {
    display: inline-flex;
  }
}

@media (max-width: 1080px) {
  .stats-grid,
  .charts-grid,
  .split-layout,
  .administration-layout {
    grid-template-columns: 1fr;
  }

  .administration-form {
    position: static;
  }

  .action-filter-grid,
  .action-create-form .form-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .meeting-history-toolbar {
    grid-template-columns: 1fr 1fr;
  }

  .meeting-history-actions,
  .meeting-history-toolbar .action-filter-result {
    grid-column: 1 / -1;
  }

}

@media (max-width: 820px) {
  .topbar,
  .topbar-actions {
    align-items: stretch;
  }

  .topbar {
    padding: 18px;
    flex-wrap: wrap;
  }

  .topbar-actions {
    width: 100%;
    justify-content: flex-start;
  }

  .search-field {
    min-width: 100%;
    max-width: none;
  }

  .content,
  .page-content {
    padding-right: 0;
  }
}

@media (max-width: 720px) {
  body.app-logged-out {
    overflow: auto;
  }

  .login-shell {
    height: auto;
    min-height: 100vh;
    min-height: 100dvh;
  }

  .login-stage {
    height: auto;
    grid-template-columns: 1fr;
  }

  .login-showcase {
    min-height: auto;
    padding: 28px 24px;
  }

  .login-panel {
    padding: 16px;
  }

  .login-card {
    padding: 18px;
  }

  .form-grid {
    grid-template-columns: 1fr;
  }

  .administration-summary {
    grid-template-columns: 1fr;
  }

  .administration-summary article {
    min-height: 0;
  }

  .login-showcase h1 {
    max-width: none;
    font-size: 2rem;
  }

  .module-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .action-workspace-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .action-filter-grid,
  .action-create-form .form-grid {
    grid-template-columns: 1fr;
