function gerotRowsInDisplayOrder(area) {
  const rows = Array.isArray(area?.rows) ? area.rows : [];
  const byId = new Map(rows.map((row) => [row.id, row]));
  const rendered = new Set();
  const memoriesFor = (row, visited = new Set()) => (Array.isArray(row.formulaInputs) ? row.formulaInputs : []).flatMap((id) => {
    if (visited.has(id)) return [];
    const memory = byId.get(id);
    if (!memory) return [];
    const next = new Set(visited).add(id);
    return [memory, ...memoriesFor(memory, next)];
  });
  const ordered = rows.filter((row) => !row.calculationInput).flatMap((row) => {
    const memories = memoriesFor(row);
    memories.forEach((memory) => rendered.add(memory.id));
    return [row, ...memories];
  });
  rows.filter((row) => row.calculationInput && !rendered.has(row.id)).forEach((row) => ordered.push(row));
  return ordered;
}

function createGerotBoard(table, area, isGeneral = false) {
  if (!table || table.dataset.boardReady === "true") return;
  table.dataset.boardReady = "true";
  const editorLayout = table.closest(".gerot-card");
  if (!editorLayout) return;
  editorLayout.dataset.gerotEditorLayout = "";
  const columnOffset = isGeneral ? 1 : 0;
  const rows = [...table.querySelectorAll("tbody tr")]
    .filter((row) => !row.classList.contains("gerot-memory-row"))
    .map((row) => {
      const cells = [...row.cells];
      const cellAt = (index) => cells[index + columnOffset];
      const kpi = cellAt(1)?.textContent.trim() || "";
      if (/^(REAL|TEND|TENDÊNCIA|TENDENCIA)$/i.test(kpi)) return "";
      const valueCell = (index) => {
        const cell = cellAt(index);
        const state = cell?.classList.contains("success") ? "success" : cell?.classList.contains("danger") ? "danger" : "";
        return '<td class="' + state + '">' + (cell?.textContent.trim() || "–") + "</td>";
      };
      const unit = cellAt(2)?.textContent.trim() || "–";
      const fy = cellAt(4)?.textContent.trim() || "–";
      const meta = cellAt(5)?.textContent.trim() || "–";
      const cia = cellAt(3)?.textContent.trim() || "–";
      const months = Array.from({ length: 12 }, (_, index) => valueCell(7 + index)).join("");
      return '<tr><th scope="row">' + (kpi || "Indicador") + "</th><td>" + unit + "</td><td>" + fy + '</td><td class="meta">' + meta + "</td><td>" + cia + "</td>" + valueCell(6) + months + "</tr>";
    }).filter(Boolean).join("");
  const board = document.createElement("section");
  board.className = "gerot-executive-board";
  board.dataset.gerotDisplayBoard = "";
  board.innerHTML = '<div class="gerot-board-banner"><span>GEROT - ' + area + '</span><small>Resultados mensais</small></div><div class="gerot-board-scroll"><table><thead><tr><th>KPI</th><th>UN</th><th>FY</th><th>META 2026</th><th>CIA</th><th>YTD</th><th>JAN</th><th>FEV</th><th>MAR</th><th>ABR</th><th>MAI</th><th>JUN</th><th>JUL</th><th>AGO</th><th>SET</th><th>OUT</th><th>NOV</th><th>DEZ</th></tr></thead><tbody>' + (rows || '<tr><td colspan="18" class="empty">Sem indicadores para exibição.</td></tr>') + '</tbody></table></div><p class="gerot-board-note">FY: EOY 2025 · CIA: comparativo 2024 · Valores atualizados conforme a memória de cálculo.</p>';
  editorLayout.before(board);
  editorLayout.hidden = true;
}

function buildGerotDisplayBoards(data) {
  if (!Array.isArray(data?.areas)) return;
  const general = elements.pageContent.querySelector("[data-gerot-general]");
  createGerotBoard(general?.querySelector(".gerot-general-table"), "GERAL", true);
  data.areas.forEach((area) => {
    const panel = elements.pageContent.querySelector('[data-gerot-panel="' + CSS.escape(area.area) + '"]');
    createGerotBoard(panel?.querySelector(".gerot-table"), area.area);
  });
}


function addGerotEditorControls(data) {
  buildGerotDisplayBoards(data);
  if (state.user?.role === "admin" || !Array.isArray(data?.areas)) return;
  data.areas.filter((area) => area.canEdit).forEach((area) => {
    const panel = elements.pageContent.querySelector('[data-gerot-panel="' + CSS.escape(area.area) + '"]');
    const table = panel?.querySelector(".gerot-table");
    if (!table || table.dataset.editorControls === "true") return;
    table.dataset.editorControls = "true";
    const header = table.querySelector("thead tr");
    if (header) header.insertAdjacentHTML("beforeend", '<th aria-label="Editar indicador"></th>');
    const orderedRows = gerotRowsInDisplayOrder(area);
    [...table.querySelectorAll("tbody tr")].forEach((tableRow, index) => {
      const row = orderedRows[index];
      const cell = document.createElement("td");
      cell.className = "gerot-indicator-actions";
      if (row && !row.calculationInput) {
        cell.innerHTML = '<button class="gerot-icon-button" type="button" data-gerot-indicator-edit="' + String(row.id).replaceAll('"', "&quot;") + '" data-gerot-indicator-area="' + String(area.area).replaceAll('"', "&quot;") + '" aria-label="Editar indicador" title="Editar indicador">✎</button>';
      }
      tableRow.appendChild(cell);
    });
  });
}

function gerotEditorArea(scope) {
  const name = scope.closest("[data-gerot-panel]")?.dataset.gerotPanel;
  return state.dataCache.gerot?.areas?.find((area) => area.area === name) || null;
}

function gerotEditorRows(scope) {
  const rows = new Map();
  scope.querySelectorAll("[data-gerot-input]").forEach((input) => {
    const id = input.dataset.gerotRow;
    if (!rows.has(id)) rows.set(id, { id, monthly: Array(12).fill(null) });
    rows.get(id).monthly[Number(input.dataset.gerotMonth)] = input.value === "" ? null : Number(input.value);
  });
  return [...rows.values()];
}

function refreshGerotPreview(scope) {
  const area = gerotEditorArea(scope);
  if (!area) return;
  const values = Object.fromEntries(gerotEditorRows(scope).map((row) => [row.id, row.monthly]));
  const preview = new Map(gerotLivePreview(area, values).map((row) => [row.id, row]));
  scope.querySelectorAll("[data-gerot-row-value]").forEach((cell) => {
    const row = preview.get(cell.dataset.gerotRowValue);
    const value = row?.monthly[Number(cell.dataset.gerotMonthValue)];
    if (!value) return;
    cell.classList.remove("success", "danger");
    if (value.status) cell.classList.add(value.status);
    const result = cell.querySelector(".gerot-result");
    if (result) result.textContent = value.display;
    else if (!cell.querySelector("input")) cell.textContent = value.display;
  });
  scope.querySelectorAll("[data-gerot-ytd]").forEach((cell) => {
    const value = preview.get(cell.dataset.gerotYtd)?.ytd;
    if (!value) return;
    cell.classList.remove("success", "danger");
    if (value.status) cell.classList.add(value.status);
    cell.textContent = value.display;
  });
  const status = scope.querySelector("[data-gerot-live-preview]");
  if (status) {
    status.hidden = false;
    status.textContent = "Resultados atualizados em tempo real · sincronizando";
  }
}

function storeGerotEditorRows(areaName, rows) {
  const area = state.dataCache.gerot?.areas?.find((item) => item.area === areaName);
  if (!area) return;
  const updates = new Map(rows.map((row) => [String(row.id), row.monthly]));
  area.rows = area.rows.map((row) => updates.has(String(row.id)) ? { ...row, monthly: [...updates.get(String(row.id))] } : row);
  area.updatedAt = new Date().toISOString();
  area.calculatedYtd = true;
}

function finishGerotEditing(scope, area) {
  const table = scope.querySelector(".gerot-table");
  scope.querySelector("[data-gerot-display-board]")?.remove();
  if (table) {
    delete table.dataset.boardReady;
    createGerotBoard(table, area);
  }
  scope.querySelector(".gerot-card")?.classList.remove("is-editing");
  scope.querySelectorAll("[data-gerot-input]").forEach((input) => { input.disabled = true; });
  const actions = elements.pageContent.querySelector("[data-gerot-master-actions]");
  const editButton = actions?.querySelector("[data-gerot-edit]");
  const saveButton = actions?.querySelector("[data-gerot-save]");
  if (editButton) editButton.hidden = false;
  if (saveButton) saveButton.hidden = true;
}

async function saveGerotEditor(scope, { silent = false } = {}) {
  const area = scope.closest("[data-gerot-panel]")?.dataset.gerotPanel || "ARMAZÉM";
  const rows = gerotEditorRows(scope);
  await api.patch(state.token, "/gerot/warehouse", { area, rows });
  storeGerotEditorRows(area, rows);
  const status = scope.querySelector("[data-gerot-live-preview]");
  if (status) {
    status.hidden = false;
    status.textContent = "Resultados compartilhados com todos os usuários";
  }
  if (!silent) showToast(`GEROT ${area} atualizado com sucesso.`);
}

function gerotSignature(data) {
  return JSON.stringify((data?.areas || []).map((area) => [area.area, area.updatedAt, (area.rows || []).map((row) => [row.id, row.monthly, row.updatedAt])]));
}

async function refreshGerotFromShared() {
  if (state.currentView !== "gerot" || elements.pageContent.querySelector(".gerot-card.is-editing")) return;
  const loaded = await views.gerot.load(api, state.token);
  const data = applyGerotAdminChanges(loaded, await loadGerotAdminChanges());
  if (gerotSignature(data) === gerotSignature(state.dataCache.gerot)) return;
  const selectedArea = elements.pageContent.querySelector("[data-gerot-area]")?.value || "GERAL";
  state.dataCache.gerot = data;
  elements.pageContent.innerHTML = views.gerot.render(data, state);
  addGerotEditorControls(data);
  const selector = elements.pageContent.querySelector("[data-gerot-area]");
  if (selector) {
    selector.value = selectedArea;
    selector.dispatchEvent(new Event("change", { bubbles: true }));
  }
}

function scheduleGerotSharedSave(scope) {
  window.clearTimeout(gerotAutoSaveTimer);
  gerotAutoSaveTimer = window.setTimeout(async () => {
    if (state.currentView !== "gerot" || !scope.isConnected) return;
    if (gerotAutoSaveRunning) {
      scheduleGerotSharedSave(scope);
      return;
    }
    gerotAutoSaveRunning = true;
    try {
      await saveGerotEditor(scope, { silent: true });
    } catch {
      const status = scope.querySelector("[data-gerot-live-preview]");
      if (status) status.textContent = "Não foi possível compartilhar agora. As alterações continuam nesta tela.";
    } finally {
      gerotAutoSaveRunning = false;
    }
  }, 750);
}

function showToast(message, tone = "success") {
  const duplicate = [...elements.toastRegion.children].find((item) => item.dataset.message === message && item.dataset.tone === tone);
  if (duplicate) {
    return;
  }
  const node = document.createElement("div");
  node.className = `toast ${tone}`;
  node.textContent = message;
  node.dataset.message = message;
  node.dataset.tone = tone;
  elements.toastRegion.appendChild(node);
  setTimeout(() => node.remove(), 3600);
}

function setButtonBusy(button, label = "Salvando...") {
  if (!button || button.dataset.busy === "true") {
    return null;
  }
  const text = button.textContent;
  button.dataset.busy = "true";
  button.disabled = true;
  button.classList.add("is-busy");
  button.textContent = label;
  return () => {
    if (!button.isConnected) return;
    button.disabled = false;
    button.classList.remove("is-busy");
    delete button.dataset.busy;
    button.textContent = text;
  };
}

