async function loadView(viewId) {
  const view = views[viewId];
  if (!view) {
    return;
  }
  const requestId = ++activeViewLoad;

  if (viewId !== "meetings") {
    stopMeetingTimer();
  }

  if (auditRefreshInterval) {
    window.clearInterval(auditRefreshInterval);
    auditRefreshInterval = null;
  }

  if (dashboardRefreshInterval) {
    window.clearInterval(dashboardRefreshInterval);
    dashboardRefreshInterval = null;
  }

  if (gerotRefreshInterval) {
    window.clearInterval(gerotRefreshInterval);
    gerotRefreshInterval = null;
  }

  if (viewId !== "actionPlans") {
    state.actionWorkspace = "list";
  }

  if (viewId !== "meetings") {
    state.meetingWorkspace = "active";
  }

  state.currentView = viewId;
  api.presence(state.token, viewId).catch(() => {});
  renderNavigation();
  elements.pageTitle.textContent = view.title;
  const cachedData = state.dataCache[viewId];
  if (cachedData) {
    elements.pageContent.classList.add("is-refreshing");
    elements.pageContent.innerHTML = view.render(cachedData, state);
    if (viewId === "gerot") addGerotEditorControls(cachedData);
  } else {
    elements.pageContent.innerHTML = `
      <div class="empty-state">
        <div>
          <h2>Carregando...</h2>
          <p>Preparando as informações.</p>
        </div>
      </div>
    `;
  }

  try {
    const loadedData = await view.load(viewId === "audit" ? auditApi : api, state.token);
    if (requestId !== activeViewLoad || state.currentView !== viewId) return;
    const data = viewId === "gerot" ? applyGerotAdminChanges(loadedData, await loadGerotAdminChanges()) : loadedData;
    if (requestId !== activeViewLoad || state.currentView !== viewId) return;
    state.dataCache[viewId] = data;
    hideStatus();
    elements.pageContent.classList.remove("is-refreshing");
    elements.pageContent.innerHTML = view.render(data, state);
    if (viewId === "gerot") addGerotEditorControls(data);

    if (viewId === "audit") {
      elements.notificationBadge.textContent = String(data.unreadCount || 0);
      auditRefreshInterval = window.setInterval(async () => {
        if (state.currentView !== "audit" || !state.token) return;
        try {
          const refreshed = await views.audit.load(auditApi, state.token);
          const previous = state.dataCache.audit;
          state.dataCache.audit = refreshed;
          const previousSignature = JSON.stringify((previous?.items || []).map((item) => [item.id, item.status, item.updatedAt]));
          const nextSignature = JSON.stringify((refreshed.items || []).map((item) => [item.id, item.status, item.updatedAt]));
          if (previousSignature === nextSignature) return;
          const activeFilters = Object.fromEntries([...elements.pageContent.querySelectorAll("[data-audit-filter]")].map((field) => [field.dataset.auditFilter, field.value]));
          elements.pageContent.innerHTML = views.audit.render(refreshed, state);
          Object.entries(activeFilters).forEach(([key, value]) => {
            const field = elements.pageContent.querySelector(`[data-audit-filter="${key}"]`);
            if (field) field.value = value;
          });
          applyAuditFilters();
        } catch {
          // Uma oscilação de sincronização não interrompe a tela atual.
        }
      }, 5000);
    }

    if (viewId === "notifications") {
      elements.notificationBadge.textContent = String(data.unreadCount || 0);
    }

    if (viewId === "dashboard") {
      elements.notificationBadge.textContent = String(data.highlights?.unreadNotifications || 0);
      dashboardRefreshInterval = window.setInterval(async () => {
        if (state.currentView !== "dashboard" || !state.token) return;
        try {
          const refreshed = await views.dashboard.load(api, state.token);
          const previous = state.dataCache.dashboard;
          const signature = (value) => JSON.stringify({ actions: (value?.actionPlans || []).map((item) => [item.id, item.status, item.dueDate, item.updatedAt]), unread: value?.highlights?.unreadNotifications || 0 });
          if (signature(previous) === signature(refreshed)) return;
          state.dataCache.dashboard = refreshed;
          elements.pageContent.innerHTML = views.dashboard.render(refreshed, state);
          elements.notificationBadge.textContent = String(refreshed.highlights?.unreadNotifications || 0);
        } catch {
          // A tela continua disponível se a sincronização oscilar.
        }
      }, 10000);
    }

    if (viewId === "gerot") {
      gerotRefreshInterval = window.setInterval(() => {
        refreshGerotFromShared().catch(() => {});
      }, 4000);
    }
  } catch (error) {
    if (requestId !== activeViewLoad || state.currentView !== viewId) return;
    elements.pageContent.classList.remove("is-refreshing");
    if (cachedData) {
      showToast("Não foi possível atualizar agora. Os últimos dados continuam disponíveis.", "warning");
      return;
    }
    renderModuleError(viewId, view.title, error, "Não foi possível abrir o módulo selecionado.");
    handleError(error, "Não foi possível abrir o módulo selecionado.");
  }
}

