  history: "Histórico"
};

const VALUE_LABELS = {
  pending: "Não iniciada",
  open: "Aberto",
  in_progress: "Em andamento",
  overdue: "Atrasado",
  done: "Concluído",
  scheduled: "Agendada",
  held: "Realizada",
  follow_up: "Follow-up",
  analysis: "Em diagnóstico",
  completed: "Concluído",
  resolved: "Resolvido",
