const GEROT_MONTHS = ["JAN", "FEV", "MAR", "ABR", "MAI", "JUN", "JUL", "AGO", "SET", "OUT", "NOV", "DEZ"];

function gerotNumber(value, unit, displayFormat = unit) {
  if (value === null || value === undefined || value === "") return "–";
  const number = Number(value);
  if (!Number.isFinite(number)) return "–";
  if (displayFormat === "%") return new Intl.NumberFormat("pt-BR", { style: "percent", minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(number);
  if (displayFormat === "HORA" || displayFormat === "MIN") {
    const seconds = Math.round(number * 86400);
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const remainingSeconds = seconds % 60;
    return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}:${String(remainingSeconds).padStart(2, "0")}`;
  }
  return new Intl.NumberFormat("pt-BR", { maximumFractionDigits: 2 }).format(number);
}

function gerotUnwrapIfError(formula) {
  const expression = String(formula || "").replace(/^=/, "").trim();
  if (!/^IFERROR\(/i.test(expression) || !expression.endsWith(")")) return expression;
  const content = expression.slice(expression.indexOf("(") + 1, -1);
  let depth = 0;
  for (let index = 0; index < content.length; index += 1) {
    if (content[index] === "(") depth += 1;
    if (content[index] === ")") depth -= 1;
    if (content[index] === "," && depth === 0) return content.slice(0, index);
  }
  return content;
}

function gerotColumnIndex(column) {
  let value = 0;
  for (const character of column) value = value * 26 + character.charCodeAt(0) - 64;
  return value - 15; // O = primeiro mês
}

function gerotSpreadsheetFormula(row, rows, formula, monthIndex, stack = new Set()) {
  if (!formula) return null;
  const key = `${row.id}:${monthIndex ?? "ytd"}`;
  if (stack.has(key)) return null;
  const nextStack = new Set(stack).add(key);
  const rowsBySheetRow = new Map(rows.map((item) => [Number(item.sheetRow), item]));
  const numeric = (value) => Number.isFinite(Number(value)) ? Number(value) : null;
  const cell = (reference) => {
    const match = String(reference).match(/^([A-Z]+)(\d+)$/);
    if (!match) return null;
    const [, column, rowNumber] = match;
    const source = rowsBySheetRow.get(Number(rowNumber));
    if (!source) return null;
    if (column === "N") return gerotYtd(source, rows, true, nextStack);
    const index = gerotColumnIndex(column);
    if (index < 0 || index > 11) return null;
    const sourceFormula = arrayValue(source.formulas)[index];
    return sourceFormula ? gerotSpreadsheetFormula(source, rows, sourceFormula, index, nextStack) : numeric(source.monthly?.[index]);
  };
  const range = (from, to) => {
    const start = String(from).match(/^([A-Z]+)(\d+)$/);
    const end = String(to).match(/^([A-Z]+)(\d+)$/);
    if (!start || !end) return [];
    const values = [];
    for (let rowNumber = Number(start[2]); rowNumber <= Number(end[2]); rowNumber += 1) {
      for (let column = gerotColumnIndex(start[1]); column <= gerotColumnIndex(end[1]); column += 1) {
        const value = cell(`${String.fromCharCode(79 + column)}${rowNumber}`);
        if (Number.isFinite(value)) values.push(value);
      }
    }
    return values;
  };
  const sum = (values) => values.reduce((total, value) => total + value, 0);
  const average = (values) => values.length ? sum(values) / values.length : null;
  const ranges = [];
  const expression = gerotUnwrapIfError(formula)
    .replace(/^IF\((SUM\([^)]*\))=0,"",\(?\1\)?\)$/i, "$1")
    .replace(/\$([A-Z]+)/g, "$1")
    .replace(/([A-Z]+\d+):([A-Z]+\d+)/g, (_, from, to) => {
      ranges.push([from, to]);
      return `__range${ranges.length - 1}__`;
    })
    .replace(/\bSUM\(/gi, "sum(")
    .replace(/\bAVERAGE\(/gi, "average(")
    .replace(/\bABS\(/gi, "abs(")
    .replace(/\b([A-Z]{1,2}\d+)\b/g, (_, reference) => `cell("${reference}")`)
    .replace(/__range(\d+)__/g, (_, index) => `range("${ranges[index][0]}", "${ranges[index][1]}")`);
  try {
    return numeric(Function("cell", "range", "sum", "average", "abs", `return (${expression});`)(cell, range, sum, average, Math.abs));
  } catch {
    return null;
  }
}

function gerotYtd(row, rows, calculatedYtd = false, stack = new Set()) {
  const hasReferenceYtd = row.referenceYtd !== null && row.referenceYtd !== undefined && row.referenceYtd !== "";
  if (!calculatedYtd && hasReferenceYtd) return row.referenceYtd;
  if (row.ytdFormula) {
    const calculated = gerotSpreadsheetFormula(row, rows, row.ytdFormula, null, stack);
    if (Number.isFinite(calculated)) return calculated;
  }
  if (arrayValue(row.formulas).some(Boolean)) {
    const values = GEROT_MONTHS.map((_, index) => gerotSpreadsheetFormula(row, rows, arrayValue(row.formulas)[index], index, stack)).filter(Number.isFinite);
    return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : hasReferenceYtd ? row.referenceYtd : null;
  }
  if (row.ytdCalculation === "source-value" && hasReferenceYtd) return row.referenceYtd;
  if (row.ytdCalculation === "source-value" && arrayValue(row.formulaInputs).length) {
    const results = GEROT_MONTHS.map((_, index) => gerotCalculatedValue(row, rows, index, calculatedYtd)).filter(Number.isFinite);
    return results.length ? results.reduce((sum, value) => sum + value, 0) / results.length : null;
  }
  if (row.ytdCalculation === "average-monthly-result") {
    const results = GEROT_MONTHS.map((_, index) => gerotCalculatedValue(row, rows, index, calculatedYtd)).filter(Number.isFinite);
    return results.length ? results.reduce((sum, value) => sum + value, 0) / results.length : null;
  }
  if (arrayValue(row.formulaInputs).length) return gerotCalculatedValue(row, rows, null, calculatedYtd);
  const values = arrayValue(row.monthly)
    .filter((value) => value !== null && value !== undefined && value !== "")
    .map(Number)
    .filter(Number.isFinite);
  if (!values.length) return null;
  const total = values.reduce((sum, value) => sum + value, 0);
  return row.aggregation === "sum" ? total : total / values.length;
}

function gerotCalculatedValue(row, rows, monthIndex, calculatedYtd = false) {
  const sourceInputsMatchPlan = monthIndex !== null && arrayValue(row.formulaInputs).every((id) => {
    const source = rows.find((item) => item.id === id);
    return Number(source?.monthly?.[monthIndex]) === Number(source?.sourceMonthly?.[monthIndex]);
  });
  if (monthIndex !== null && arrayValue(row.monthlySourceOverrides).includes(monthIndex) && sourceInputsMatchPlan) {
    const sourceResult = Number(row.monthly?.[monthIndex]);
    if (Number.isFinite(sourceResult)) return sourceResult;
  }
  const valueFor = (id) => {
    const source = rows.find((item) => item.id === id);
    if (monthIndex === null) return gerotYtd(source, rows, calculatedYtd);
    const value = source?.monthly?.[monthIndex];
    return value === null || value === undefined || value === "" ? null : Number(value);
  };
  const [a, b, c, d, e, f] = arrayValue(row.formulaInputs).map(valueFor);
  if (![a, b].every(Number.isFinite)) return null;
  const assistantHours = row.id === "pnp" && monthIndex === 0 ? 7.35 : monthIndex !== null && monthIndex >= 9 ? 7.83 : monthIndex !== null && monthIndex >= 7 ? 7.35 : 7.36;
  switch (row.id) {
    case "eficiencia-carregamento": case "aderencia-wms": case "matriz-priorizacao": return b ? a / b : null;
    case "eficiencia-descarga": return a + b ? a / (a + b) : null;
    case "stock-age": return a ? 1 - b / a : null;
    case "stock-age-curva-c": return a + b ? a / (a + b) : null;
    case "txr-armazem": return b ? 1 - a / b : null;
    case "wlp": return c && d ? c / ((a * assistantHours + b * 7.33) * d) : null;
    case "pnp": return a && b ? a / ((c * assistantHours + d * 7.33 + e * 8.33 + f * 8.08) * b) : null;
    case "fnp": return b ? a / b : null;
    case "tqi": return b ? a / b * 1000000 : null;
    case "pallets-avariados": return b ? a / b : null;
    default: return null;
  }
}

export function gerotLivePreview(area, inputValues = {}) {
  const rows = arrayValue(area?.rows).map((row) => ({ ...row, monthly: [...arrayValue(row.monthly)] }));
  Object.entries(inputValues).forEach(([id, months]) => {
    const row = rows.find((item) => String(item.id) === String(id));
    if (!row) return;
    Object.entries(months || {}).forEach(([month, value]) => {
      const index = Number(month);
      if (index >= 0 && index < 12) row.monthly[index] = value === "" || value === null ? null : Number(value);
    });
  });
  return rows.map((row) => {
    const monthly = GEROT_MONTHS.map((_, index) => {
      const formula = arrayValue(row.formulas)[index];
      const value = formula
        ? gerotSpreadsheetFormula(row, rows, formula, index)
        : arrayValue(row.formulaInputs).length
          ? gerotCalculatedValue(row, rows, index, true)
          : row.monthly?.[index];
      return { value, display: gerotNumber(value, row.unit, row.displayFormat), status: gerotGoalClass(row, value) };
    });
    const ytd = gerotYtd(row, rows, true);
    return { id: String(row.id), ytd: { value: ytd, display: gerotNumber(ytd, row.unit, row.displayFormat), status: gerotGoalClass(row, ytd) }, monthly };
  });
}

function gerotGoalClass(row, value) {
  if (row.goalMode === "none") return "neutral";
  if (!Number.isFinite(Number(value))) return "neutral";
  if (row.goalMode === "higher") return Number(value) >= Number(row.target) ? "success" : "danger";
  if (row.goalMode === "lower") return Number(value) <= Number(row.target) ? "success" : "danger";
  if (row.goalMode === "absolute") return Math.abs(Number(value)) <= Math.abs(Number(String(row.target).replace(/[^0-9.,-]/g, "").replace(",", "."))) ? "success" : "danger";
  return Number(value) >= Number(row.targetMin) && Number(value) <= Number(row.targetMax) ? "success" : "danger";
}

function gerotGoalLabel(row) {
  if (row.goalMode === "none") return "Memória";
  if (row.goalMode === "absolute") return String(row.target || "–");
  if (row.goalMode === "range") return `${gerotNumber(row.targetMin, row.unit, row.displayFormat)} a ${gerotNumber(row.targetMax, row.unit, row.displayFormat)}`;
  return gerotNumber(row.target, row.unit, row.displayFormat);
}

function gerotGeneralView(areas) {
  const months = GEROT_MONTHS;
  const rows = areas.flatMap((area) => {
    const areaRows = arrayValue(area.rows);
    return areaRows.filter((row) => !row.calculationInput).map((row) => {
      const ytd = gerotYtd(row, areaRows, Boolean(area.calculatedYtd));
      const monthly = months.map((month, index) => {
        const spreadsheetFormula = arrayValue(row.formulas)[index];
        const calculated = spreadsheetFormula && area.calculatedYtd
          ? gerotSpreadsheetFormula(row, areaRows, spreadsheetFormula, index)
          : arrayValue(row.formulaInputs).length
            ? gerotCalculatedValue(row, areaRows, index, Boolean(area.calculatedYtd))
            : row.monthly?.[index];
        const value = calculated ?? row.monthly?.[index];
        return `<td class="gerot-value ${gerotGoalClass(row, value)}">${gerotNumber(value, row.unit, row.displayFormat)}</td>`;
      }).join("");
      return `<tr><td><span class="gerot-area-badge">${escapeHtml(area.area)}</span></td><td>${escapeHtml(row.type)}</td><td><strong>${escapeHtml(row.indicator)}</strong></td><td>${escapeHtml(row.unit)}</td><td>${gerotNumber(row.eoy2024, row.unit, row.displayFormat)}</td><td>${gerotNumber(row.eoy2025, row.unit, row.displayFormat)}</td><td>${gerotGoalLabel(row)}</td><td class="gerot-value ${gerotGoalClass(row, ytd)}">${gerotNumber(ytd, row.unit, row.displayFormat)}</td>${monthly}</tr>`;
    });
  }).join("");
  return `<section data-gerot-general>
    <p class="gerot-legend"><span class="badge success">Meta atingida</span><span class="badge danger">Meta não atingida</span><span>Visão consolidada somente para consulta.</span></p>
    <section class="table-card gerot-card gerot-general-card"><div class="table-scroll"><table class="gerot-table gerot-general-table"><thead><tr><th>Área</th><th>Tipo</th><th>Indicador</th><th>Un.</th><th>EOY 2024</th><th>EOY 2025</th><th>Meta 2026</th><th>YTD 2026</th>${months.map((month) => `<th>${month}</th>`).join("")}</tr></thead><tbody>${rows}</tbody></table></div></section>
  </section>`;
}

function gerotWarehouseView(data, context = {}) {
  if (Array.isArray(data.areas)) {
    const year = data.areas[0]?.year || 2026;
    const isAdmin = context.user?.role === "admin";
    const sharedActions = data.areas.some((area) => area.canEdit) ? `<div class="gerot-editor-actions" data-gerot-master-actions hidden>${isAdmin ? `<button class="gerot-icon-button" type="button" data-gerot-indicator-add aria-label="Incluir indicador" title="Incluir indicador">＋</button>` : ""}<button class="button secondary" type="button" data-gerot-edit>Editar mês</button><button class="button primary" type="button" data-gerot-save hidden>Salvar alterações</button></div>` : "";
    return `${moduleHeader("GEROT", "Quadro geral de indicadores operacionais por área.")}
      <section class="gerot-toolbar gerot-consultation"><div class="gerot-title-block"><span class="eyebrow">QUADRO DE CONSULTA</span><strong data-gerot-master-title>GERAL · GEROT ${escapeHtml(year)}</strong><small data-gerot-master-summary>Todos os indicadores consolidados.</small></div><div class="gerot-toolbar-actions"><label class="gerot-area-field"><span>Área</span><select data-gerot-area aria-label="Selecionar área do GEROT"><option>GERAL</option>${data.areas.map((area) => `<option>${escapeHtml(area.area)}</option>`).join("")}</select></label><button class="button secondary" type="button" data-export="gerot">Exportar GEROT</button>${sharedActions}</div></section>${gerotGeneralView(data.areas)}${data.areas.map((area) => `<div data-gerot-panel="${escapeHtml(area.area)}" data-gerot-can-edit="${Boolean(area.canEdit)}" data-gerot-panel-summary="${escapeHtml(area.calculatedYtd ? "Acumulado recalculado a partir das memórias preenchidas." : "Acumulado inicial espelhado da planilha de referência.")}" hidden>${gerotWarehouseView({ ...area, embedded: true }, context)}</div>`).join("")}`;
  }
  const months = GEROT_MONTHS;
  const isAdmin = context.user?.role === "admin";
  const allRows = arrayValue(data.rows);
  const indicatorCount = allRows.filter((row) => !row.calculationInput).length;
  const rowsById = new Map(allRows.map((row) => [row.id, row]));
  const renderedMemoryRows = new Set();
  const memoryRowsFor = (row, visited = new Set()) => arrayValue(row.formulaInputs).flatMap((id) => {
    if (visited.has(id)) return [];
    const memoryRow = rowsById.get(id);
    if (!memoryRow) return [];
    const nextVisited = new Set(visited).add(id);
    return [memoryRow, ...memoryRowsFor(memoryRow, nextVisited)];
  });
  const orderedRows = allRows.filter((row) => !row.calculationInput).flatMap((row) => {
    const memoryRows = memoryRowsFor(row);
    memoryRows.forEach((memoryRow) => renderedMemoryRows.add(memoryRow.id));
    return [row, ...memoryRows];
  });
  allRows.filter((row) => row.calculationInput && !renderedMemoryRows.has(row.id)).forEach((row) => orderedRows.push(row));
  const rows = orderedRows.map((row) => {
    const ytd = gerotYtd(row, allRows, Boolean(data.calculatedYtd));
    const monthly = months.map((month, index) => {
      const spreadsheetFormula = arrayValue(row.formulas)[index];
      const calculated = spreadsheetFormula && data.calculatedYtd ? gerotSpreadsheetFormula(row, allRows, spreadsheetFormula, index) : arrayValue(row.formulaInputs).length ? gerotCalculatedValue(row, allRows, index, Boolean(data.calculatedYtd)) : row.monthly?.[index];
      const value = calculated ?? row.monthly?.[index];
      const status = gerotGoalClass(row, value);
      const editable = !arrayValue(row.formulaInputs).length && !arrayValue(row.formulas).some(Boolean);
      return `<td class="gerot-value ${status}" data-gerot-row-value="${escapeHtml(row.id)}" data-gerot-month-value="${index}" data-label="${month}">${editable ? `<span class="gerot-result">${gerotNumber(value, row.unit, row.displayFormat)}</span><input data-gerot-input data-gerot-row="${escapeHtml(row.id)}" data-gerot-month="${index}" type="number" step="any" value="${value ?? ""}" disabled aria-label="${escapeHtml(row.indicator)} em ${month}">` : gerotNumber(value, row.unit, row.displayFormat)}</td>`;
    }).join("");
    const indicatorActions = isAdmin && !row.calculationInput ? `<td class="gerot-indicator-actions"><button class="gerot-icon-button" type="button" data-gerot-indicator-edit="${escapeHtml(row.id)}" data-gerot-indicator-area="${escapeHtml(data.area)}" aria-label="Editar indicador" title="Editar indicador">✎</button><button class="gerot-icon-button danger" type="button" data-gerot-indicator-delete="${escapeHtml(row.id)}" data-gerot-indicator-area="${escapeHtml(data.area)}" aria-label="Excluir indicador" title="Excluir indicador">🗑</button></td>` : isAdmin ? "<td></td>" : "";
    return `<tr class="${row.calculationInput ? "gerot-memory-row" : ""}"><td>${escapeHtml(row.type)}</td><td><strong>${escapeHtml(row.indicator)}</strong></td><td>${escapeHtml(row.unit)}</td><td>${gerotNumber(row.eoy2024, row.unit, row.displayFormat)}</td><td>${gerotNumber(row.eoy2025, row.unit, row.displayFormat)}</td><td>${gerotGoalLabel(row)}</td><td class="gerot-value ${gerotGoalClass(row, ytd)}" data-gerot-ytd="${escapeHtml(row.id)}">${gerotNumber(ytd, row.unit, row.displayFormat)}</td>${monthly}${indicatorActions}</tr>`;
  }).join("");
  const canEdit = Boolean(data.canEdit);
  const ytdSummary = data.calculatedYtd ? "Acumulado recalculado a partir das memórias preenchidas." : "Acumulado inicial espelhado da planilha de referência.";
  return `
    ${data.embedded ? "" : moduleHeader("GEROT", "Quadro geral de indicadores operacionais.")}
    ${data.embedded ? "" : `<section class="gerot-toolbar gerot-consultation"><div class="gerot-title-block"><span class="eyebrow">QUADRO DE CONSULTA</span><strong data-gerot-title>${escapeHtml(data.area || "ARMAZÉM")} · GEROT ${escapeHtml(data.year || 2026)}</strong><small data-gerot-summary data-gerot-default-summary="${escapeHtml(ytdSummary)}">${escapeHtml(ytdSummary)}</small></div><div class="gerot-toolbar-actions">${canEdit ? `<div class="gerot-editor-actions"><button class="button secondary" type="button" data-gerot-edit><span>Editar mês</span></button><button class="button primary" type="button" data-gerot-save hidden>Salvar alterações</button></div>` : ""}</div></section>`}
    <section class="gerot-summary-strip" data-gerot-details><span><strong>${indicatorCount}</strong> indicadores</span><span><strong>${escapeHtml(data.year || 2026)}</strong> competência</span><span>Visualização para todos os usuários</span><span class="gerot-live-status" data-gerot-live-preview hidden></span>${!canEdit ? `<span>Edição exclusiva: ${escapeHtml(data.area || "Armazém")} e Gabriely</span>` : ""}</section>
    <section data-gerot-details><p class="gerot-legend"><span class="badge success">Meta atingida</span><span class="badge danger">Meta não atingida</span><span>Metas avaliadas conforme direção ou faixa definida na planilha.</span></p>
    <section class="table-card gerot-card"><div class="table-scroll"><table class="gerot-table"><thead><tr><th>Tipo</th><th>Indicador</th><th>Unidade</th><th>EOY 2024</th><th>EOY 2025</th><th>Meta 2026</th><th>YTD 2026</th>${months.map((month) => `<th>${month}</th>`).join("")}${isAdmin ? "<th aria-label=\"Ações\"></th>" : ""}</tr></thead><tbody>${rows}</tbody></table></div></section></section>
  `;
}

